            customSqlQuery12.Sql = resources.GetString("customSqlQuery12.Sql");
            customSqlQuery13.Name = "Query_2";
            customSqlQuery13.Sql = "SELECT items.id as \'Code\',items.name as \'Item\',items.sale_rate as \'Sale Rate\',si." +
    "sold_qty as \'Qty\' from items left join sale_items as si on items.id=si.item_id";
            customSqlQuery14.Name = "Query_3";
            customSqlQuery14.Sql = "SELECT ac.id as \'Code\',ac.name as \'Name\',ac.balance as \'Balance\' from accounts as" +
    " ac left join account_groups as ag on ac.account_group_id=ag.id WHERE ag.nature=" +
    "\'Expense\';\r\n\r\n";
            customSqlQuery15.Name = "agreement_dues";
            customSqlQuery15.Sql = "SELECT emi_date as \'Due Date\',emi_amount as \'Due Amount\' FROM aggrement_dues as a" +
    "d WHERE paid_amount <= 0\r\n";
